import{_ as e,o as a,c as s,an as i}from"./chunks/framework.C1Zpw0WN.js";const p=JSON.parse('{"title":"Conventions cheat sheet","description":"","frontmatter":{},"headers":[],"relativePath":"preprocessing/conventions.md","filePath":"preprocessing/conventions.md","lastUpdated":null}'),n={name:"preprocessing/conventions.md"};function o(d,t,r,l,c,h){return a(),s("div",null,[...t[0]||(t[0]=[i(`<h1 id="Conventions-cheat-sheet" tabindex="-1">Conventions cheat sheet <a class="header-anchor" href="#Conventions-cheat-sheet" aria-label="Permalink to &quot;Conventions cheat sheet {#Conventions-cheat-sheet}&quot;">​</a></h1><p>The single-page reference for unit conventions, hard-coded constants, auto-detected formats, and replay tolerances. Useful when you&#39;re debugging an unexpected binary header or trying to consume an external dataset that doesn&#39;t quite match the runtime contract.</p><h2 id="mass_flux_dt-450-s-—-the-FV3-dynamics-step" tabindex="-1"><code>mass_flux_dt = 450 s</code> — the FV3 dynamics step <a class="header-anchor" href="#mass_flux_dt-450-s-—-the-FV3-dynamics-step" aria-label="Permalink to &quot;\`mass_flux_dt = 450 s\` — the FV3 dynamics step {#mass_flux_dt-450-s-—-the-FV3-dynamics-step}&quot;">​</a></h2><p>GEOS / FV3 native <code>MFXC</code> and <code>MFYC</code> are accumulated over the <strong>dynamics timestep</strong> (default 450 s for GEOS-IT C180), not the 1-hour met window. Treating them as per-second rates without dividing by <code>mass_flux_dt</code> makes transport ~8× too slow.</p><table tabindex="0"><thead><tr><th style="text-align:right;">Where</th><th style="text-align:right;">What</th></tr></thead><tbody><tr><td style="text-align:right;"><code>[preprocessing] mass_flux_dt_seconds</code> (source-descriptor TOML, e.g. <code>config/met_sources/geosit.toml</code>)</td><td style="text-align:right;">The scalar a user must set. Defaults to <code>450.0</code>.</td></tr><tr><td style="text-align:right;"><code>src/Preprocessing/sources/geos.jl::read_window!</code></td><td style="text-align:right;">Where the division happens (<code>am ∝ MFXC / mass_flux_dt</code>); the GEOS-CS orchestrator then converts the per-second rate to the binary&#39;s <code>flux_kind = :substep_mass_amount</code> units before write.</td></tr><tr><td style="text-align:right;"><code>state.air_mass</code> after one window</td><td style="text-align:right;">Should remain <code>O(1)</code> relative to its starting value; an <code>O(8)</code> jump means the constant got missed.</td></tr></tbody></table><p>Spectral preprocessing does not have an equivalent constant — Holton synthesis already produces per-second rates.</p><h2 id="Dry-basis-conversion" tabindex="-1">Dry-basis conversion <a class="header-anchor" href="#Dry-basis-conversion" aria-label="Permalink to &quot;Dry-basis conversion {#Dry-basis-conversion}&quot;">​</a></h2><p><code>DELP_dry = DELP_moist · (1 − qv)</code> is applied at the cell-center level; for face-staggered fluxes the dry factor is the average of the two adjacent cell-center <code>(1 − qv)</code> values.</p><table tabindex="0"><thead><tr><th style="text-align:right;">Path</th><th style="text-align:right;">Function</th><th style="text-align:right;">Where</th></tr></thead><tbody><tr><td style="text-align:right;">Spectral ERA5 (LL/RG/CS)</td><td style="text-align:right;"><code>apply_dry_basis_native!</code></td><td style="text-align:right;"><code>src/Preprocessing/mass_support.jl</code> — runs after spectral synthesis, before binary write.</td></tr><tr><td style="text-align:right;">GEOS native CS</td><td style="text-align:right;"><code>endpoint_dry_mass!</code> (centers) + face-averaging</td><td style="text-align:right;"><code>src/Preprocessing/sources/geos.jl</code> — runs at endpoint reconstruction.</td></tr><tr><td style="text-align:right;">GEOS convection forcing (cmfmc / dtrain)</td><td style="text-align:right;"><code>_moist_to_dry_cmfmc!</code>, <code>_moist_to_dry_dtrain!</code></td><td style="text-align:right;"><code>src/Preprocessing/sources/geos.jl</code> — runs in the convection-read block.</td></tr></tbody></table><p><code>MFXC</code> / <code>MFYC</code> from GEOS are special: per the GMAO product documentation they are <strong>already on a dry basis</strong>. Don&#39;t apply the correction twice.</p><h2 id="Level-orientation" tabindex="-1">Level orientation <a class="header-anchor" href="#Level-orientation" aria-label="Permalink to &quot;Level orientation {#Level-orientation}&quot;">​</a></h2><p>GEOS-IT files are <strong>bottom-up</strong> (level index 1 is the surface, level index <code>Nz</code> is the top of the model). The runtime expects <strong>top-down</strong> (level 1 = TOA, level <code>Nz</code> = surface). The reader auto-detects and flips once at read time.</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">src</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Preprocessing</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sources</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">geos</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">jl</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">detect_level_orientation</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(ctm_a1)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    -&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> :bottom_up</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> :top_down</span></span></code></pre></div><p>The heuristic compares <code>mean(DELP[:, :, :, 1, 1])</code> against <code>mean(DELP[:, :, :, Nz, 1])</code> — the surface DELP is <code>O(1000 Pa)</code> and the TOA DELP is <code>O(1 Pa)</code>, so the ordering is unambiguous.</p><p>NetCDF <code>lev:positive</code> attributes are not consulted in the current GEOS reader; level orientation comes from the DELP-magnitude heuristic above. A non-GMAO source for which that heuristic is invalid needs a dedicated reader method instead of relying on this path.</p><p>ERA5 spectral output is already top-down; no flip needed.</p><h2 id="Panel-conventions-cubed-sphere-only" tabindex="-1">Panel conventions (cubed-sphere only) <a class="header-anchor" href="#Panel-conventions-cubed-sphere-only" aria-label="Permalink to &quot;Panel conventions (cubed-sphere only) {#Panel-conventions-cubed-sphere-only}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Convention</th><th style="text-align:right;">Symbol</th><th style="text-align:right;">Equatorial panels</th><th style="text-align:right;">North</th><th style="text-align:right;">South</th></tr></thead><tbody><tr><td style="text-align:right;">Gnomonic</td><td style="text-align:right;"><code>:gnomonic</code></td><td style="text-align:right;">1, 2, 3, 4</td><td style="text-align:right;">5</td><td style="text-align:right;">6</td></tr><tr><td style="text-align:right;">GEOS-native</td><td style="text-align:right;"><code>:geos_native</code></td><td style="text-align:right;">1, 2, 4, 5</td><td style="text-align:right;">3</td><td style="text-align:right;">6</td></tr></tbody></table><p>The preprocessor writes the active convention into the binary header as <code>panel_convention</code>. The runtime reads it back and constructs the matching <code>PanelConnectivity</code> (panel-edge wiring used to rotate fluxes across panel boundaries). <strong>Picking the wrong convention silently produces panel-edge artifacts</strong> — every diagnostic tool emits the panel layout schematic so this is easy to verify visually; see the <a href="/AtmosTransport.jl/stable/concepts/grids#Grids">Cubed-sphere section of the Grids page</a> for the side-by-side schematic.</p><h2 id="Units-in-the-binary-payload" tabindex="-1">Units in the binary payload <a class="header-anchor" href="#Units-in-the-binary-payload" aria-label="Permalink to &quot;Units in the binary payload {#Units-in-the-binary-payload}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Section</th><th style="text-align:right;">Unit</th><th style="text-align:right;">Basis</th><th style="text-align:right;">Layout</th></tr></thead><tbody><tr><td style="text-align:right;"><code>:m</code></td><td style="text-align:right;"><strong>kg per cell</strong></td><td style="text-align:right;">matches <code>mass_basis</code> header</td><td style="text-align:right;"><code>(Nx, Ny, Nz)</code> LL / <code>(ncells, Nz)</code> RG / <code>NTuple{6, (Nc, Nc, Nz)}</code> CS</td></tr><tr><td style="text-align:right;"><code>:am</code></td><td style="text-align:right;"><strong>kg per substep</strong> (<code>flux_kind = :substep_mass_amount</code>; multiply by <code>steps_per_window</code> for per-window total)</td><td style="text-align:right;">matches header</td><td style="text-align:right;">LL: <code>(Nx+1, Ny, Nz)</code>; CS: <code>(Nc+1, Nc, Nz)</code> per panel (canonical + halo)</td></tr><tr><td style="text-align:right;"><code>:bm</code></td><td style="text-align:right;"><strong>kg per substep</strong></td><td style="text-align:right;">matches header</td><td style="text-align:right;">LL: <code>(Nx, Ny+1, Nz)</code>; CS: <code>(Nc, Nc+1, Nz)</code> per panel</td></tr><tr><td style="text-align:right;"><code>:hflux</code></td><td style="text-align:right;"><strong>kg per substep</strong></td><td style="text-align:right;">matches header</td><td style="text-align:right;">RG only — face-indexed <code>(nface_h, Nz)</code></td></tr><tr><td style="text-align:right;"><code>:cm</code></td><td style="text-align:right;"><strong>kg per substep</strong></td><td style="text-align:right;">matches header</td><td style="text-align:right;">extends <code>Nz</code> by 1 along the vertical axis</td></tr><tr><td style="text-align:right;"><code>:ps</code></td><td style="text-align:right;">Pa</td><td style="text-align:right;">dry if <code>mass_basis = :dry</code></td><td style="text-align:right;"><code>(Nx, Ny)</code> LL etc.</td></tr><tr><td style="text-align:right;"><code>:dm</code></td><td style="text-align:right;"><strong>kg per cell</strong></td><td style="text-align:right;">matches header</td><td style="text-align:right;">per-window mass tendency for the explicit-<code>dm</code> replay closure</td></tr><tr><td style="text-align:right;"><code>:qv_start</code>/<code>:qv_end</code></td><td style="text-align:right;">kg / kg</td><td style="text-align:right;">(water-mass mixing ratio is basis-agnostic)</td><td style="text-align:right;">optional endpoint pair — set when <code>[output] include_qv = true</code></td></tr><tr><td style="text-align:right;"><code>:cmfmc</code></td><td style="text-align:right;">kg / m² / s</td><td style="text-align:right;">dry-converted by the GEOS reader</td><td style="text-align:right;">NZ+1 interfaces</td></tr><tr><td style="text-align:right;"><code>:dtrain</code></td><td style="text-align:right;">kg / m² / s</td><td style="text-align:right;">dry-converted by the GEOS reader</td><td style="text-align:right;">NZ centers</td></tr><tr><td style="text-align:right;"><code>:entu</code>, <code>:detu</code>, <code>:entd</code>, <code>:detd</code></td><td style="text-align:right;">kg / m² / s</td><td style="text-align:right;">dry</td><td style="text-align:right;">NZ centers, all four required together for <code>TM5Convection</code></td></tr><tr><td style="text-align:right;"><code>:pblh</code>, <code>:ustar</code>, <code>:pbl_hflux</code>, <code>:t2m</code></td><td style="text-align:right;">SI surface quantities</td><td style="text-align:right;">basis-agnostic</td><td style="text-align:right;">per-cell surface fields; all four together feed <code>WindowPBLKzField</code></td></tr><tr><td style="text-align:right;"><code>:vdiff_u</code>, <code>:vdiff_v</code>, <code>:vdiff_t</code>, <code>:vdiff_qv</code></td><td style="text-align:right;">m/s, K, kg/kg at substep cadence</td><td style="text-align:right;">dry where applicable</td><td style="text-align:right;">NZ centers, feeds <code>LocalHoltslagBovilleKzField</code></td></tr></tbody></table><p>The transport-binary core fields (<code>:m</code>, <code>:am</code>, <code>:bm</code>, <code>:cm</code>, <code>:dm</code>) are stored as <strong>per-cell mass</strong> and <strong>per-substep mass amount</strong> (<code>flux_kind = :substep_mass_amount</code>), not per-area / per-second fluxes. The runtime advection step consumes them directly without unit conversion. Convection forcing arrays (<code>:cmfmc</code>, <code>:dtrain</code>, <code>:entu</code>, …) come from external met physics and stay in their native per-area-per-second units; the operator handles the multiplication by <code>dt</code> at apply time.</p><div class="tip custom-block"><p class="custom-block-title">Current format only</p><p>Maintained writers emit transport-binary version 4 and maintained readers reject earlier formats. Use <code>inspect_binary</code> to verify data rather than inferring a format from a directory name.</p></div><h2 id="Replay-tolerances" tabindex="-1">Replay tolerances <a class="header-anchor" href="#Replay-tolerances" aria-label="Permalink to &quot;Replay tolerances {#Replay-tolerances}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">FT</th><th style="text-align:right;"><code>replay_tolerance(FT)</code></th></tr></thead><tbody><tr><td style="text-align:right;"><code>Float64</code></td><td style="text-align:right;"><code>1e-10</code></td></tr><tr><td style="text-align:right;"><code>Float32</code></td><td style="text-align:right;"><code>1e-4</code></td></tr></tbody></table><p>Defined in <code>src/MetDrivers/ReplayContinuity.jl</code>. Used by:</p><ul><li><p><strong>Write-time gate</strong> in every preprocessing path (<code>verify_storage_continuity_*!</code>, <code>verify_write_replay_cs!</code>). Failures abort the run.</p></li><li><p><strong>Opt-in load-time gate</strong> at runtime. Enable via the env var <code>ATMOSTR_REPLAY_CHECK=1</code> or by constructing the driver with <code>validate_replay = true</code> (driver kwarg, not a TOML key). Failures throw an <code>ArgumentError</code> pointing at the worst-cell location.</p></li></ul><p>The asymmetry between F64 and F32 reflects the noise floor: F32 arithmetic at production resolutions accumulates rounding to ~<code>1e-5</code> per substep, so a <code>1e-10</code> gate would false-positive on healthy F32 binaries.</p><h2 id="Per-source-data-layout-cheat-sheet" tabindex="-1">Per-source data layout cheat sheet <a class="header-anchor" href="#Per-source-data-layout-cheat-sheet" aria-label="Permalink to &quot;Per-source data layout cheat sheet {#Per-source-data-layout-cheat-sheet}&quot;">​</a></h2><h3 id="ERA5-spectral" tabindex="-1">ERA5 spectral <a class="header-anchor" href="#ERA5-spectral" aria-label="Permalink to &quot;ERA5 spectral {#ERA5-spectral}&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/data/AtmosTransport/met/era5/</span></span>
<span class="line"><span>└── 0.5x0.5/</span></span>
<span class="line"><span>    ├── spectral_hourly/</span></span>
<span class="line"><span>    │   ├── era5_spectral_YYYYMMDD_lnsp.gb     # log surface pressure</span></span>
<span class="line"><span>    │   └── era5_spectral_YYYYMMDD_vo_d.gb     # vorticity + divergence</span></span>
<span class="line"><span>    └── physics/</span></span>
<span class="line"><span>        └── era5_thermo_ml_YYYYMMDD.nc          # specific humidity</span></span></code></pre></div><h3 id="GEOS-IT-C180-native" tabindex="-1">GEOS-IT C180 native <a class="header-anchor" href="#GEOS-IT-C180-native" aria-label="Permalink to &quot;GEOS-IT C180 native {#GEOS-IT-C180-native}&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/data/AtmosTransport/met/geosit/C180/native/</span></span>
<span class="line"><span>├── GEOSIT.YYYYMMDD.CTM_A1.C180.nc              # MFXC, MFYC, DELP (hourly)</span></span>
<span class="line"><span>├── GEOSIT.YYYYMMDD.CTM_I1.C180.nc              # PS, QV (hourly instantaneous)</span></span>
<span class="line"><span>├── GEOSIT.YYYYMMDD.A3mstE.C180.nc              # CMFMC (3-hourly)  — convection</span></span>
<span class="line"><span>└── GEOSIT.YYYYMMDD.A3dyn.C180.nc               # DTRAIN (3-hourly) — convection</span></span></code></pre></div><p>The day after the requested range is also required (for the last window&#39;s forward-flux endpoints).</p><h2 id="v4-header-fields-preprocessor-set" tabindex="-1">v4 header fields (preprocessor-set) <a class="header-anchor" href="#v4-header-fields-preprocessor-set" aria-label="Permalink to &quot;v4 header fields (preprocessor-set) {#v4-header-fields-preprocessor-set}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Field</th><th style="text-align:right;">Required?</th><th style="text-align:right;">Notes</th></tr></thead><tbody><tr><td style="text-align:right;"><code>format_version</code></td><td style="text-align:right;">yes</td><td style="text-align:right;">Must be <code>4</code> — every other version is rejected.</td></tr><tr><td style="text-align:right;"><code>steps_per_window_by_window :: Vector{Int}</code></td><td style="text-align:right;">yes</td><td style="text-align:right;">Length <code>nwindow</code>. Per-window adaptive substep count (GEOS-CS) or constant (spectral).</td></tr><tr><td style="text-align:right;"><code>poisson_balance_target_scale_by_window :: Vector{Float64}</code></td><td style="text-align:right;">yes</td><td style="text-align:right;">Length <code>nwindow</code>. Scale factor used by the per-window balance step.</td></tr><tr><td style="text-align:right;"><code>time_step_schedule</code></td><td style="text-align:right;">yes</td><td style="text-align:right;"><code>&quot;constant&quot;</code> if all entries of <code>steps_per_window_by_window</code> are equal, else <code>&quot;per_window&quot;</code>.</td></tr><tr><td style="text-align:right;"><code>runtime_substep_contract</code></td><td style="text-align:right;">optional</td><td style="text-align:right;"><code>&quot;binary_schedule&quot;</code> (CS only) — tells the runtime to advance using the per-window schedule.</td></tr><tr><td style="text-align:right;"><code>geos_mass_endpoint</code></td><td style="text-align:right;">optional (CS GEOS only)</td><td style="text-align:right;"><code>&quot;raw_dry_endpoint&quot;</code> — records that the mass target is the raw GEOS dry endpoint, not the pressure-fixer endpoint.</td></tr><tr><td style="text-align:right;"><code>ps_offsets_pa_per_window</code></td><td style="text-align:right;">optional (LL spectral only)</td><td style="text-align:right;">Per-window PS offsets applied by <code>pin_global_mean_ps!</code>.</td></tr><tr><td style="text-align:right;"><code>preprocessor_contract</code></td><td style="text-align:right;">optional (CS only)</td><td style="text-align:right;">Free-form tag, e.g. <code>&quot;plan41_variable_substeps&quot;</code>.</td></tr></tbody></table><h2 id="What&#39;s-next" tabindex="-1">What&#39;s next <a class="header-anchor" href="#What&#39;s-next" aria-label="Permalink to &quot;What&amp;#39;s next {#What&#39;s-next}&quot;">​</a></h2><ul><li><p><a href="./../getting_started/inspecting_output">Inspecting output</a> — verify a freshly-built binary.</p></li><li><p><a href="./../concepts/binary_format">Concepts: binary format</a> — the full header schema and capability surface.</p></li></ul>`,38)])])}const y=e(n,[["render",o]]);export{p as __pageData,y as default};
